     1	package hotel.documents;
     2	
     3	import hotel.reservations.Reservation;
     4	import hotel.rooms.Room;
     5	import hotel.rooms.RoomType;
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	
     9	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
    10	public record ReservationReceipt(
    11	        String title,
    12	        long reservationId,
    13	        String guestName,
    14	        String guestCpf,
    15	        int roomNumber,
    16	        RoomType roomType,
    17	        LocalDate checkIn,
    18	        LocalDate checkOut,
    19	        int nights,
    20	        BigDecimal subtotal,
    21	        BigDecimal discount,
    22	        BigDecimal total) {
    23	
    24	    public ReservationReceipt(Reservation reservation, Room room) {
    25	        this(
    26	                "Comprovante de reserva",
    27	                reservation.id(),
    28	                reservation.guest().name(),
    29	                reservation.guest().cpf(),
    30	                room.number(),
    31	                room.type(),
    32	                reservation.checkIn(),
    33	                reservation.checkOut(),
    34	                reservation.price().nights(),
    35	                reservation.price().subtotal(),
    36	                reservation.price().discount(),
    37	                reservation.price().total());
    38	    }
    39	
    40	    public String text() {
    41	        StringBuilder text = new StringBuilder();
    42	        text.append(title).append(" nº ").append(reservationId).append('\n');
    43	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    44	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    45	        text.append("Entrada: ").append(TextFormat.date(checkIn))
    46	                .append(" | Saída: ").append(TextFormat.date(checkOut))
    47	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    48	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
    49	        if (discount.signum() > 0) {
    50	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
    51	        }
    52	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
    53	        return text.toString();
    54	    }
    55	}
        // the check-out day is free for the next guest, and another room is free on the same nights
        service.create(stay(201, "2027-03-13", "2027-03-15", 2, RatePlan.STANDARD));
        service.create(stay(202, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
    }

    @Test
    void aCancelledReservationFreesTheRoom() {
        Reservation first = service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
        service.cancel(first.id());

        service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
    }

    @Test
    void confirmingSendsTheReceiptByEmail() {
        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));

        service.confirm(reservation.id());

        assertEquals(ReservationStatus.CONFIRMED, service.find(reservation.id()).status());
        List<Message> sent = sentMessages.all();
        assertEquals(1, sent.size());
        assertEquals("EMAIL", sent.get(0).channel());
        assertEquals("ana@example.com", sent.get(0).to());
        assertEquals("Sua reserva na Pousada Maré Alta está confirmada!", sent.get(0).subject());
        assertTrue(sent.get(0).body().contains("Desconto: R$ 37,48"));
        assertTrue(sent.get(0).body().contains("Total: R$ 212,42"));
    }

    @Test
    void onlyAPendingReservationCanBeConfirmed() {
        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
        service.confirm(reservation.id());

        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, errorOf(() -> service.confirm(reservation.id())));
        assertEquals(1, sentMessages.all().size());
    }

